  const fieldMeta={m:['木块质量 m','kg'],M:['木板质量 M','kg'],L:['木板长度 L','m'],v0:['木块初速度 v₀','m/s'],mu:['动摩擦因数 μ',''],g:['重力加速度 g','m/s²'],side:['底面腰长 AB=AC','长度单位'],base:['底边长 BC','长度单位'],height:['侧棱长 AA₁','长度单位'],ratio:['共同分点比例 r','0<r<1；中点为 0.5']};
