    return pageHead(`${result.title} · 首答、提示与订正分别保存。`,go('查看知识变化','profile','','network')+go('继续探索模型','physics','primary','cube'))+`<section class="result-hero"><div><div class="eyebrow">LEARNING FEEDBACK</div><h2 style="margin:7px 0">看清这一次，也找到下一步。</h2><p class="muted" style="font-size:12px;margin:5px 0">${eligible.length?`本次有效独立首答 ${independentCorrect}/${eligible.length} 正确（${fmt(independentCorrect/eligible.length*100,1)}%）。`:'本次为辅助学习或重复练习，没有新增独立首答。'} ${correctionIds.size?`${correctionIds.size} 题在提示或解析后完成订正。`:''}</p></div><div class="result-score">${correct}<small> / ${items.length} 首次作答正确</small></div></section><div class="main-aside" style="margin-top:22px"><div><div class="section-head" style="margin-top:0"><h2>逐题回看</h2><span class="subtle">重复打开结果不重复计入指标</span></div>${items.map((r,i)=>{const q=question(r.qid),corrected=correctionIds.has(r.qid);return `<section class="panel result-card"><div class="row between"><span class="code-label">${String(i+1).padStart(2,'0')} / ${r.qid} · ${kp(q.primary_knowledge_id)?.name||'自定义'}</span><div class="row">${tag(r.answer===''?'未作答':r.correct?'首答正确':'首答错误',r.correct?'green':'red')}${!r.eligible?tag('辅助 / 重复练习','outline'):''}${corrected?tag('已订正','green'):''}</div></div><p class="q-title">${esc(q.prompt)}</p><div class="answer-comparison"><span>你的首答：<b class="${r.correct?'correct':'incorrect'}">${esc(r.answer===''?'未作答':r.answer)} ${r.answer!==''?esc(q.unit||''):''}</b></span><span>正确答案：<b class="correct">${esc(q.answer)} ${esc(q.unit||'')}</b></span></div><details><summary>展开解析与复习建议</summary><p>${esc(q.explanation)}</p><div class="row wrap">${go('回到模型',q.subject==='mathematics'?'geometry':'physics','small')}${!r.correct&&!corrected&&r.answer!==''?btn('查看提示并订正','correct-question','small',`data-id="${q.id}"`):''}</div></details></section>`;}).join('')}</div><aside class="stack"><section class="panel"><h2>知识参考指标</h2>${['K01','K02','K03','K04','K05'].map(id=>{const b=result.before?.[id],a=after[id];return `<div class="list-row"><div class="row between"><strong>${kp(id).name}</strong>${tag(a.status,statusClass(a))}</div><div class="row between" style="margin-top:8px"><span class="subtle">${b?`${pct(b)} → `:''}${pct(a)}</span><span class="subtle">${a.correct}/${a.n}</span></div></div>`;}).join('')}<p class="subtle">提示后订正不覆盖首答；没有新增题目的指标保持不变。</p></section><section class="panel soft"><h3>接下来，可以这样学</h3><p>对照受力图，区分“撤去拉力”和“合力变为零”。再用一题不同条件的练习检查理解。</p>${go('观察撤力后的运动','physics','small')}${btn('查看完整统计规则','metric-rule','small ghost')}</section></aside></div>`;
