  function settingsDrawer() {closeOverlay();$('#overlay').innerHTML=`<div class="drawer-scrim" data-act="close-overlay"></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="演示设置"><div class="row between"><h2>演示设置</h2>${btn('关闭','close-overlay','small')}</div><p class="subtle">所有人物与作答均为虚构。下面的重置只影响此原型在当前浏览器中的记录。</p><label class="field"><span>切换数据阶段</span><select id="demo-stage"><option value="diagnosed" ${state.stage==='diagnosed'?'selected':''}>诊断完成 · 默认入口</option><option value="history" ${state.stage==='history'?'selected':''}>仅历史练习 · 尚未诊断</option><option value="after" ${state.stage==='after'?'selected':''}>针对练习完成 · 草稿结果</option><option value="empty" ${state.stage==='empty'?'selected':''}>新学生 · 无个人记录</option></select></label>${btn('载入此阶段并重置','reset-demo','primary wide')}<div class="notice">会清除当前浏览器中自行作答、保存和发布的内容，重新载入示例。</div><label class="check"><input id="service-fail" type="checkbox" ${state.serviceFail?'checked':''}>模拟条件提取 / 组织题目服务失败</label><p class="subtle">失败时可以手动确认条件或改用已审核题库，模型和已有记录仍可打开。</p>${btn('导出当前演示记录','export-records','wide','','save')}<details><summary>实现范围</summary><p>已实现：本地交互、物理公式、几何视角、统计、作答及发布快照。<br>模拟：图片识别、AI 配题与提示。<br>未实现：真实登录、服务端权限、跨设备同步。</p></details></aside>`;}
  function editQuestion(id) {const q=question(id);closeOverlay();$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="修改候选题"><h2>修改候选题</h2><p class="subtle">保存为新的题目版本，历史作答不会被修改；发布前需要重新审核。</p><label class="field"><span>题目</span><textarea id="edit-prompt">${esc(q.prompt)}</textarea></label><div class="field-grid"><label class="field"><span>标准答案${q.type==='single_choice'?'（选项字母）':''}</span><input id="edit-answer" type="${q.type==='numeric'?'number':'text'}" step="any" value="${esc(q.answer)}"></label><label class="field"><span>答案单位</span><input id="edit-unit" value="${esc(q.unit||'')}" ${q.type==='single_choice'?'disabled':''}></label></div><label class="field"><span>解析</span><textarea id="edit-explanation" style="min-height:90px">${esc(q.explanation)}</textarea></label><div id="edit-error" class="notice error"></div><div class="modal-actions">${btn('取消','close-overlay')}${btn('保存为新版本','save-edited-question','primary',`data-id="${id}"`)}</div></section></div>`;}
